+        display: grid;
+        place-items: center;
+        min-height: 100vh;
+        padding: 2rem 1rem;
+      }
+
+      .card {
+        width: min(100%, 30rem);
+        padding: clamp(1.5rem, 5vw, 2.5rem);
+        background: var(--card-bg);
+        border: 1px solid #e2e8f0;
+        border-radius: 1.5rem;
+        box-shadow: var(--shadow);
+      }
+
+      .eyebrow {
+        margin: 0 0 0.5rem;
+        color: var(--primary);
+        font-size: 0.78rem;
+        font-weight: 700;
+        letter-spacing: 0.08em;
+        text-transform: uppercase;
+      }
+
+      h1 {
+        margin: 0;
+        font-size: clamp(2rem, 7vw, 2.75rem);
+        line-height: 1.05;
+        letter-spacing: -0.045em;
+      }
+
+      .intro {
+        margin: 1rem 0 1.75rem;
+        color: var(--muted);
+      }
+
+      .form-field {
+        display: grid;
+        grid-template-columns: auto 1fr;
+        gap: 0.75rem;
+        align-items: start;
+        padding: 1rem;
+        border: 1px solid var(--border);
+        border-radius: 1rem;
+        background: #fbfdff;
+      }
+
+      .form-field input[type="checkbox"] {
+        width: 1.25rem;
+        height: 1.25rem;
+        margin: 0.15rem 0 0;
+        accent-color: var(--primary);
+        cursor: pointer;
+      }
+
+      label {
+        font-weight: 700;
+      }
+
+      .helper-text {
+        grid-column: 2;
+        margin: -0.45rem 0 0;
+        color: var(--muted);
+        font-size: 0.94rem;
+      }
+
+      button {
+        width: 100%;
+        margin-top: 1.25rem;
+        padding: 0.9rem 1.1rem;
+        color: #ffffff;
+        font: inherit;
+        font-weight: 800;
+        background: var(--primary);
+        border: 0;
+        border-radius: 0.9rem;
+        cursor: pointer;
+        transition:
+          background-color 160ms ease,
+          transform 160ms ease;
+      }
+
+      button:hover {
+        background: var(--primary-hover);
+      }
+
+      button:active {
+        transform: translateY(1px);
+      }
+
+      a {
+        color: var(--primary);
+        font-weight: 700;
+      }
+
+      a:hover {
+        color: var(--primary-hover);
+      }
+
+      input:focus-visible,
+      button:focus-visible,
+      a:focus-visible {
+        outline: 3px solid transparent;
+        box-shadow: 0 0 0 4px var(--focus);
+      }
+
+      .status {
+        min-height: 1.5rem;
+        margin: 1rem 0 0;
+        color: #0f6b44;
+        font-weight: 700;
+      }
+
+      @media (max-width: 22rem) {
+        .form-field {
+          grid-template-columns: 1fr;
+        }
+
+        .helper-text {
+          grid-column: 1;
+          margin-top: 0;
+        }
+      }
+
+      @media (forced-colors: active) {
+        .card,
+        .form-field,
+        button {
+          border: 1px solid ButtonBorder;
+        }
+
+        input:focus-visible,
+        button:focus-visible,
+        a:focus-visible,
+        .skip-link:focus {
+          outline: 3px solid ButtonText;
+          box-shadow: none;
+        }
+      }
+    </style>
+  </head>
+  <body>
+    <a class="skip-link" href="#main">Skip to main content</a>
+    <div id="root"></div>
+
+    <script>
+      const ConsentCheckbox = () => `
+        <div class="form-field">
+          <input
+            id="terms"
+            name="terms"
+            type="checkbox"
+            required
+            aria-describedby="terms-helper"
+          />
+          <label for="terms">
+            I agree to the <a href="/terms">terms of use</a>
+          </label>
+          <p class="helper-text" id="terms-helper">
+            Required to create and manage your account.
+          </p>
+        </div>
+      `;
+
+      const ConsentForm = () => `
+        <form id="consent-form" novalidate>
+          ${ConsentCheckbox()}
+          <button type="submit">Submit agreement</button>
+          <p class="status" id="form-status" role="status" aria-live="polite"></p>
+        </form>
+      `;
+
+      const App = () => `
+        <main class="page-shell" id="main">
+          <section class="card" aria-labelledby="page-title">
+            <p class="eyebrow">Terms consent</p>
+            <h1 id="page-title">Review and continue</h1>
+            <p class="intro">
+              Please confirm that you accept the terms before submitting.
+            </p>
+            ${ConsentForm()}
+          </section>
+        </main>
+      `;
+
+      document.getElementById("root").innerHTML = App();
+
+      document
+        .getElementById("consent-form")
+        .addEventListener("submit", (event) => {
+          event.preventDefault();
+
+          const form = event.currentTarget;
+          const checkbox = document.getElementById("terms");
+          const status = document.getElementById("form-status");
+
+          if (!checkbox.checked) {
+            checkbox.setAttribute("aria-invalid", "true");
