+            checkbox.focus();
+            return;
+          }
+
+          checkbox.removeAttribute("aria-invalid");
+          form.reset();
+          status.textContent = "Thanks. Your agreement has been submitted.";
+        });
+    </script>
+  </body>
+</html>
*** End Patch
